'use client';

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { api, ApiError } from '@/lib/api';
import { CheckCircle, AlertCircle, Key, Building, Hash } from 'lucide-react';

export default function ProfilePage() {
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  // FBR Credentials state
  const [fbrAccessToken, setFbrAccessToken] = useState('');
  const [fbrEnvironment, setFbrEnvironment] = useState('SANDBOX');
  const [fbrSellerNtn, setFbrSellerNtn] = useState('');
  const [fbrBusinessName, setFbrBusinessName] = useState('');
  const [hasExistingToken, setHasExistingToken] = useState(false);

  useEffect(() => {
    fetchFbrCredentials();
  }, []);

  const fetchFbrCredentials = async () => {
    try {
      setLoading(true);
      const response = await api.auth.getFbrCredentials();

      setFbrEnvironment(response.fbr_environment || 'SANDBOX');
      setFbrSellerNtn(response.fbr_seller_ntn || '');
      setFbrBusinessName(response.fbr_business_name || '');
      setHasExistingToken(response.has_fbr_token || false);
    } catch (err) {
      console.error('Error fetching FBR credentials:', err);
      setError('Failed to load FBR credentials');
    } finally {
      setLoading(false);
    }
  };

  const handleSaveFbrCredentials = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!fbrAccessToken && !hasExistingToken) {
      setError('Please enter your FBR access token');
      return;
    }

    try {
      setSaving(true);
      setError(null);
      setSuccess(null);

      const credentials: any = {
        fbr_environment: fbrEnvironment,
        fbr_seller_ntn: fbrSellerNtn,
        fbr_business_name: fbrBusinessName,
      };

      // Only include token if user entered a new one
      if (fbrAccessToken) {
        credentials.fbr_access_token = fbrAccessToken;
      }

      const response = await api.auth.updateFbrCredentials(credentials);

      setSuccess('FBR credentials updated successfully!');
      setHasExistingToken(response.has_fbr_token);
      setFbrAccessToken(''); // Clear the token input for security

      // Refresh credentials
      await fetchFbrCredentials();
    } catch (err) {
      if (err instanceof ApiError) {
        setError(err.message);
      } else {
        setError('Failed to update FBR credentials');
      }
      console.error('Error updating FBR credentials:', err);
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600 mx-auto"></div>
          <p className="mt-4 text-gray-600">Loading profile...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 max-w-4xl">
      <div>
        <h1 className="text-3xl font-bold text-gray-900">Profile Settings</h1>
        <p className="mt-2 text-gray-600">Manage your FBR integration credentials</p>
      </div>

      {/* Success Message */}
      {success && (
        <div className="bg-green-50 border border-green-200 rounded-lg p-4">
          <div className="flex items-start gap-3">
            <CheckCircle className="h-5 w-5 text-green-600 flex-shrink-0 mt-0.5" />
            <div>
              <h3 className="text-sm font-medium text-green-800">Success</h3>
              <p className="mt-1 text-sm text-green-700">{success}</p>
            </div>
          </div>
        </div>
      )}

      {/* Error Message */}
      {error && (
        <div className="bg-red-50 border border-red-200 rounded-lg p-4">
          <div className="flex items-start gap-3">
            <AlertCircle className="h-5 w-5 text-red-600 flex-shrink-0 mt-0.5" />
            <div>
              <h3 className="text-sm font-medium text-red-800">Error</h3>
              <p className="mt-1 text-sm text-red-700">{error}</p>
            </div>
          </div>
        </div>
      )}

      {/* FBR Credentials Card */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Key className="h-5 w-5" />
            FBR Integration Credentials
          </CardTitle>
          <CardDescription>
            Configure your Federal Board of Revenue (FBR) API credentials for invoice validation and posting.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSaveFbrCredentials} className="space-y-6">
            {/* Token Status */}
            {hasExistingToken && (
              <div className="p-3 bg-green-50 border border-green-200 rounded-lg">
                <div className="flex items-center gap-2">
                  <CheckCircle className="h-4 w-4 text-green-600" />
                  <span className="text-sm text-green-800 font-medium">
                    FBR Access Token is configured
                  </span>
                </div>
                <p className="text-xs text-green-700 mt-1">
                  Leave the token field empty to keep your existing token, or enter a new one to update it.
                </p>
              </div>
            )}

            {/* FBR Access Token */}
            <div>
              <Label htmlFor="fbrAccessToken" className="flex items-center gap-2">
                <Key className="h-4 w-4" />
                FBR Access Token {!hasExistingToken && '*'}
              </Label>
              <Input
                id="fbrAccessToken"
                type="password"
                value={fbrAccessToken}
                onChange={(e) => setFbrAccessToken(e.target.value)}
                placeholder={hasExistingToken ? "Enter new token to update" : "Enter your FBR API access token"}
                className="mt-1"
              />
              <p className="text-xs text-gray-500 mt-1">
                Your FBR API access token from the FBR Digital Invoicing Portal
              </p>
            </div>

            {/* Environment */}
            <div>
              <Label htmlFor="fbrEnvironment">Environment *</Label>
              <Select value={fbrEnvironment} onValueChange={setFbrEnvironment}>
                <SelectTrigger className="mt-1">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="SANDBOX">Sandbox (Testing)</SelectItem>
                  <SelectItem value="PRODUCTION">Production (Live)</SelectItem>
                </SelectContent>
              </Select>
              <p className="text-xs text-gray-500 mt-1">
                Use Sandbox for testing, Production for live invoices
              </p>
            </div>

            {/* Seller NTN */}
            <div>
              <Label htmlFor="fbrSellerNtn" className="flex items-center gap-2">
                <Hash className="h-4 w-4" />
                Seller NTN/CNIC
              </Label>
              <Input
                id="fbrSellerNtn"
                type="text"
                value={fbrSellerNtn}
                onChange={(e) => setFbrSellerNtn(e.target.value)}
                placeholder="Enter your 7-digit NTN or 13-digit CNIC"
                className="mt-1"
              />
              <p className="text-xs text-gray-500 mt-1">
                Your National Tax Number (7 digits) or CNIC (13 digits)
              </p>
            </div>

            {/* Business Name */}
            <div>
              <Label htmlFor="fbrBusinessName" className="flex items-center gap-2">
                <Building className="h-4 w-4" />
                Business Name
              </Label>
              <Input
                id="fbrBusinessName"
                type="text"
                value={fbrBusinessName}
                onChange={(e) => setFbrBusinessName(e.target.value)}
                placeholder="Enter your registered business name"
                className="mt-1"
              />
              <p className="text-xs text-gray-500 mt-1">
                Your business name as registered with FBR
              </p>
            </div>

            {/* Information Box */}
            <div className="p-4 bg-blue-50 border border-blue-200 rounded-lg">
              <h4 className="text-sm font-medium text-blue-900 mb-2">How to get FBR credentials:</h4>
              <ol className="text-sm text-blue-800 space-y-1 list-decimal list-inside">
                <li>Register at FBR Digital Invoicing Portal: <a href="https://e.fbr.gov.pk" target="_blank" rel="noopener noreferrer" className="underline">https://e.fbr.gov.pk</a></li>
                <li>Complete the registration and verification process</li>
                <li>Navigate to API Settings to generate your access token</li>
                <li>Copy the token and paste it here</li>
              </ol>
            </div>

            {/* Save Button */}
            <div className="flex justify-end gap-3">
              <Button
                type="submit"
                disabled={saving}
                className="bg-indigo-600 hover:bg-indigo-700"
              >
                {saving ? 'Saving...' : 'Save FBR Credentials'}
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}
